/* From Uiverse.io by csozidev - Tags: simple, black, loader, loop */
/* Simple loader made by: csozi | Website: www.csozi.hu*/

.__UIV_SCOPE__ .loader {
  height: 50px;
  width: 50px;
  position: relative;
}

.__UIV_SCOPE__ .block {
  height: 10px;
  width: 10px;
  background-color: black;
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .b_1 {
  top: 0;
  left: 0;
  animation: load 2s infinite;
  animation-delay: 0;
}

.__UIV_SCOPE__ .b_2 {
  top: 0;
  left: 20px;
  animation: load 2s infinite;
  animation-delay: 0.25s;
}

.__UIV_SCOPE__ .b_3 {
  top: 0;
  right: 0;
  animation: load 2s infinite;
  animation-delay: 0.5s;
}

.__UIV_SCOPE__ .b_4 {
  top: 20px;
  right: 0;
  animation: load 2s infinite;
  animation-delay: 0.75s;
}

.__UIV_SCOPE__ .b_5 {
  bottom: 0;
  right: 0;
  animation: load 2s infinite;
  animation-delay: 1s;
}

.__UIV_SCOPE__ .b_6 {
  bottom: 0;
  left: 20px;
  animation: load 2s infinite;
  animation-delay: 1.25s;
}

.__UIV_SCOPE__ .b_7 {
  bottom: 0;
  left: 0;
  animation: load 2s infinite;
  animation-delay: 1.5s;
}

.__UIV_SCOPE__ .b_8 {
  top: 20px;
  left: 0;
  animation: load 2s infinite;
  animation-delay: 1.75s;
}

@keyframes load {
  0% {
    opacity: 1;
  }

  85% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}
